'use strict';

// MODULES //

var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var EPS = require( '@stdlib/constants/float32/eps' );
var absf = require( '@stdlib/math/base/special/absf' );
var randu = require( '@stdlib/random/base/randu' );
var fresnelf = require( './../lib/main.js' );


// FIXTURES //

var smallPositive = require( './fixtures/c/small.json' );
var mediumPositive = require( './fixtures/c/medium.json' );
var largePositive = require( './fixtures/c/large.json' );
var hugePositive = require( './fixtures/c/huge.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof fresnelf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function computes Fresnel integrals (small positive values)', function test( t ) {
	var expectedS;
	var expectedC;
	var delta;
	var tol;
	var C;
	var S;
	var x;
	var y;
	var i;

	x = smallPositive.x;
	S = smallPositive.S;
	C = smallPositive.C;

	for ( i = 0; i < x.length; i++ ) {
		y = fresnelf( x[i] );
		expectedS = float64ToFloat32( S[i] );
		expectedC = float64ToFloat32( C[i] );
		if ( y[0] === expectedS ) {
			t.strictEqual( y[0], expectedS, 'x: ' + x[i] + '. Expected: ' + expectedS );
		} else {
			delta = absf( y[0] - expectedS );
			tol = 10.0 * EPS * absf( expectedS );

			t.ok( delta <= tol, 'within tolerance. x: ' + x[i] + '. S: ' + y[0] + '. Expected: ' + S[i] + '. tol: ' + tol + '. delta: ' + delta + '.' );
		}
		if ( y[1] === expectedC ) {
			t.strictEqual( y[1], expectedC, 'x: ' + x[i] + '. Expected: ' + expectedC );
		} else {
			delta = absf( y[1] - expectedC );
			tol = 10.0 * EPS * absf( expectedC );

			t.ok( delta <= tol, 'within tolerance. x: ' + x[i] + '. C: ' + y[1] + '. Expected: ' + expectedC + '. tol: ' + tol + '. delta: ' + delta + '.' );
		}
	}
	t.end();
});

